 return <><DashboardShell user={user} store={store} stores={stores} view={route.view} plan={plan.plan} onSignOut={signout} onSelectStore={selectStore} onNewStore={()=>setSetup(true)}>{busy&&<div className="top-loading-line"/>}{page}</DashboardShell>{receiptOrder&&<Receipt order={receiptOrder} store={store} onClose={()=>setReceiptOrder(null)}/>} {setup&&<StoreSetup loading={busy} onCreate={createStore}/>} {productModal&&<ProductModal product={productModal.id?productModal:null} onClose={()=>setProductModal(null)} onSave={saveProduct} busy={busy}/>} {share&&<ShareModal url={shareUrl} onClose={()=>setShare(false)}/>}<Notice value={notice} onClose={()=>setNotice(null)}/></>;
